SELECT (MAX("COMBINED_AGES") * CAST(%s AS INTEGER)) FROM (SELECT SUM(("AGGREGATION_AUTHOR"."AGE" + T3."AGE")) AS "COMBINED_AGES" FROM "AGGREGATION_AUTHOR" LEFT OUTER JOIN "AGGREGATION_AUTHOR_FRIENDS" ON ("AGGREGATION_AUTHOR"."ID" = "AGGREGATION_AUTHOR_FRIENDS"."FROM_AUTHOR_ID") LEFT OUTER JOIN "AGGREGATION_AUTHOR" T3 ON ("AGGREGATION_AUTHOR_FRIENDS"."TO_AUTHOR_ID" = T3."ID") GROUP BY "AGGREGATION_AUTHOR"."ID") subquery;
SELECT (MAX("COMBINED_AGES") + MAX("COMBINED_AGES")) FROM (SELECT SUM(("AGGREGATION_AUTHOR"."AGE" + T3."AGE")) AS "COMBINED_AGES" FROM "AGGREGATION_AUTHOR" LEFT OUTER JOIN "AGGREGATION_AUTHOR_FRIENDS" ON ("AGGREGATION_AUTHOR"."ID" = "AGGREGATION_AUTHOR_FRIENDS"."FROM_AUTHOR_ID") LEFT OUTER JOIN "AGGREGATION_AUTHOR" T3 ON ("AGGREGATION_AUTHOR_FRIENDS"."TO_AUTHOR_ID" = T3."ID") GROUP BY "AGGREGATION_AUTHOR"."ID") subquery;
SELECT (MAX("COMBINED_AGES") + MAX("COMBINED_AGES")), (SUM("COMBINED_AGES") + SUM("COMBINED_AGES")) FROM (SELECT SUM(("AGGREGATION_AUTHOR"."AGE" + T3."AGE")) AS "COMBINED_AGES" FROM "AGGREGATION_AUTHOR" LEFT OUTER JOIN "AGGREGATION_AUTHOR_FRIENDS" ON ("AGGREGATION_AUTHOR"."ID" = "AGGREGATION_AUTHOR_FRIENDS"."FROM_AUTHOR_ID") LEFT OUTER JOIN "AGGREGATION_AUTHOR" T3 ON ("AGGREGATION_AUTHOR_FRIENDS"."TO_AUTHOR_ID" = T3."ID") GROUP BY "AGGREGATION_AUTHOR"."ID") subquery;
SELECT (MAX("COMBINED_AGES") + MAX("COMBINED_AGES")), SUM("COMBINED_AGES") FROM (SELECT SUM(("AGGREGATION_AUTHOR"."AGE" + T3."AGE")) AS "COMBINED_AGES" FROM "AGGREGATION_AUTHOR" LEFT OUTER JOIN "AGGREGATION_AUTHOR_FRIENDS" ON ("AGGREGATION_AUTHOR"."ID" = "AGGREGATION_AUTHOR_FRIENDS"."FROM_AUTHOR_ID") LEFT OUTER JOIN "AGGREGATION_AUTHOR" T3 ON ("AGGREGATION_AUTHOR_FRIENDS"."TO_AUTHOR_ID" = T3."ID") GROUP BY "AGGREGATION_AUTHOR"."ID") subquery;
SELECT AVG(CAST("AUTHORS_COUNT" AS DOUBLE)) FROM (SELECT COUNT("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID") AS "AUTHORS_COUNT" FROM "AGGREGATION_BOOK" LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" ON ("AGGREGATION_BOOK"."ID" = "AGGREGATION_BOOK_AUTHORS"."BOOK_ID") GROUP BY "AGGREGATION_BOOK"."ID") subquery;
SELECT AVG(CAST("MAX_PK" AS DOUBLE)) FROM (SELECT MAX("AGGREGATION_BOOK"."ID") AS "MAX_PK" FROM "AGGREGATION_BOOK" GROUP BY "AGGREGATION_BOOK"."ID") subquery;
SELECT AVG(CAST("NUM_AUTHORS" AS DOUBLE)) FROM (SELECT COUNT("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID") AS "NUM_AUTHORS" FROM "AGGREGATION_BOOK" LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" ON ("AGGREGATION_BOOK"."ID" = "AGGREGATION_BOOK_AUTHORS"."BOOK_ID") GROUP BY "AGGREGATION_BOOK"."ID") subquery;
SELECT AVG("PAGES_PER_AUTHOR") FROM (SELECT (ANY_VALUE("DJDB2I_GROUPING"."G1") / CAST(COUNT("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID") AS DOUBLE)) AS "PAGES_PER_AUTHOR" FROM "AGGREGATION_BOOK" LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" ON ("AGGREGATION_BOOK"."ID" = "AGGREGATION_BOOK_AUTHORS"."BOOK_ID") CROSS JOIN LATERAL (SELECT GREATEST("AGGREGATION_BOOK"."PAGES", CAST(%s AS INTEGER)) AS "G1" FROM SYSIBM.SYSDUMMY1) AS "DJDB2I_GROUPING" GROUP BY "DJDB2I_GROUPING"."G1") subquery;
SELECT AVG("__COL1") FROM (SELECT "AGGREGATION_BOOK"."RATING" AS "__COL1" FROM "AGGREGATION_BOOK" LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" ON ("AGGREGATION_BOOK"."ID" = "AGGREGATION_BOOK_AUTHORS"."BOOK_ID") INNER JOIN "AGGREGATION_BOOK_AUTHORS" T4 ON ("AGGREGATION_BOOK"."ID" = T4."BOOK_ID") INNER JOIN "AGGREGATION_AUTHOR" T5 ON (T4."AUTHOR_ID" = T5."ID") WHERE T5."NAME" LIKE %s ESCAPE '\' GROUP BY "AGGREGATION_BOOK"."ID", "AGGREGATION_BOOK"."RATING" HAVING COUNT("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID") > %s) subquery;
SELECT AVG("__COL1") FROM (SELECT "AGGREGATION_BOOK"."RATING" AS "__COL1" FROM "AGGREGATION_BOOK" ORDER BY "AGGREGATION_BOOK"."RATING" DESC FETCH FIRST 3 ROWS ONLY) subquery;
SELECT COUNT(*) FROM ((SELECT "AGGREGATION_AUTHOR"."AGE" AS "AGE", CAST(%s AS INTEGER) AS "OTHER" FROM "AGGREGATION_AUTHOR") UNION (SELECT CAST(%s AS INTEGER) AS "AGE", CAST(%s AS INTEGER) AS "OTHER" FROM "AGGREGATION_BOOK")) subquery;
SELECT COUNT(*) FROM (SELECT (SELECT U0."ID" AS "PK" FROM "AGGREGATION_AUTHOR" U0 INNER JOIN "AGGREGATION_BOOK_AUTHORS" U1 ON (U0."ID" = U1."AUTHOR_ID") INNER JOIN "AGGREGATION_BOOK" U2 ON (U1."BOOK_ID" = U2."ID") WHERE (U2."NAME" = ("AGGREGATION_BOOK"."NAME") AND U0."ID" = ("AGGREGATION_AUTHOR"."ID"))) AS "SUBQUERY_ID" FROM "AGGREGATION_AUTHOR" LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" ON ("AGGREGATION_AUTHOR"."ID" = "AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID") LEFT OUTER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_BOOK_AUTHORS"."BOOK_ID" = "AGGREGATION_BOOK"."ID") GROUP BY "AGGREGATION_AUTHOR"."ID", (SELECT U0."ID" AS "PK" FROM "AGGREGATION_AUTHOR" U0 INNER JOIN "AGGREGATION_BOOK_AUTHORS" U1 ON (U0."ID" = U1."AUTHOR_ID") INNER JOIN "AGGREGATION_BOOK" U2 ON (U1."BOOK_ID" = U2."ID") WHERE (U2."NAME" = ("AGGREGATION_BOOK"."NAME") AND U0."ID" = ("AGGREGATION_AUTHOR"."ID")))) subquery;
SELECT COUNT(*) FROM (SELECT DISTINCT "AGGREGATION_AUTHOR"."ID" AS "COL1", "AGGREGATION_AUTHOR"."NAME" AS "COL2", "AGGREGATION_AUTHOR"."AGE" AS "COL3", "AGGREGATION_AUTHOR"."RATING" AS "COL4" FROM "AGGREGATION_AUTHOR" INNER JOIN "AGGREGATION_BOOK_AUTHORS" ON ("AGGREGATION_AUTHOR"."ID" = "AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID") WHERE "AGGREGATION_BOOK_AUTHORS"."BOOK_ID" IN (%s, %s)) subquery;
SELECT COUNT(*) FROM (SELECT "AGGREGATION_BOOK"."ID" AS "COL1" FROM "AGGREGATION_BOOK" LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" ON ("AGGREGATION_BOOK"."ID" = "AGGREGATION_BOOK_AUTHORS"."BOOK_ID") GROUP BY "AGGREGATION_BOOK"."ID") subquery;
SELECT COUNT(*) FROM (SELECT "AGGREGATION_PUBLISHER"."ID" AS "ID", "AGGREGATION_PUBLISHER"."NAME" AS "NAME", "DJDB2I_GROUPING"."G1" AS "GOOD_BOOK" FROM "AGGREGATION_PUBLISHER" LEFT OUTER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_PUBLISHER"."ID" = "AGGREGATION_BOOK"."PUBLISHER_ID") CROSS JOIN LATERAL (SELECT CASE WHEN "AGGREGATION_BOOK"."RATING" > %s THEN CAST(%s AS BOOLEAN) ELSE CAST(%s AS BOOLEAN) END AS "G1" FROM SYSIBM.SYSDUMMY1) AS "DJDB2I_GROUPING" GROUP BY "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "DJDB2I_GROUPING"."G1") subquery;
SELECT COUNT(*) FROM (SELECT "DJDB2I_GROUPING"."G1" AS "GOOD_BOOK" FROM "AGGREGATION_PUBLISHER" LEFT OUTER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_PUBLISHER"."ID" = "AGGREGATION_BOOK"."PUBLISHER_ID") CROSS JOIN LATERAL (SELECT CASE WHEN "AGGREGATION_BOOK"."RATING" > %s THEN CAST(%s AS BOOLEAN) ELSE CAST(%s AS BOOLEAN) END AS "G1" FROM SYSIBM.SYSDUMMY1) AS "DJDB2I_GROUPING" GROUP BY "AGGREGATION_PUBLISHER"."ID", "DJDB2I_GROUPING"."G1") subquery;
SELECT COUNT(*) FROM (SELECT "DJDB2I_GROUPING"."G1" AS "PAGES_MOD" FROM "AGGREGATION_BOOK" CROSS JOIN LATERAL (SELECT MOD("AGGREGATION_BOOK"."PAGES", CAST(%s AS INTEGER)) AS "G1" FROM SYSIBM.SYSDUMMY1) AS "DJDB2I_GROUPING" GROUP BY "DJDB2I_GROUPING"."G1") subquery;
SELECT COUNT(CASE WHEN "EARLIEST_BOOK_YEAR" = %s THEN "__COL1" ELSE NULL END) FROM (SELECT (SELECT YEAR(U0."PUBDATE") AS "PUBDATE__YEAR" FROM "AGGREGATION_BOOK" U0 WHERE U0."CONTACT_ID" = ("AGGREGATION_AUTHOR"."ID") ORDER BY U0."PUBDATE" ASC FETCH FIRST 1 ROWS ONLY) AS "EARLIEST_BOOK_YEAR", "AGGREGATION_AUTHOR"."ID" AS "__COL1" FROM "AGGREGATION_AUTHOR") subquery;
SELECT COUNT(CASE WHEN "__COL1" = ("MAX_BOOK_AUTHOR") THEN "__COL1" ELSE NULL END) FROM (SELECT MAX(T4."AUTHOR_ID") AS "MAX_BOOK_AUTHOR", "AGGREGATION_AUTHOR"."ID" AS "__COL1" FROM "AGGREGATION_AUTHOR" LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" ON ("AGGREGATION_AUTHOR"."ID" = "AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID") LEFT OUTER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_BOOK_AUTHORS"."BOOK_ID" = "AGGREGATION_BOOK"."ID") LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" T4 ON ("AGGREGATION_BOOK"."ID" = T4."BOOK_ID") GROUP BY "AGGREGATION_AUTHOR"."ID") subquery;
SELECT COUNT(CASE WHEN "__COL1" IN ("MAX_BOOK_AUTHOR", CAST(%s AS INTEGER)) THEN "__COL1" ELSE NULL END) FROM (SELECT MAX(T4."AUTHOR_ID") AS "MAX_BOOK_AUTHOR", "AGGREGATION_AUTHOR"."ID" AS "__COL1" FROM "AGGREGATION_AUTHOR" LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" ON ("AGGREGATION_AUTHOR"."ID" = "AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID") LEFT OUTER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_BOOK_AUTHORS"."BOOK_ID" = "AGGREGATION_BOOK"."ID") LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" T4 ON ("AGGREGATION_BOOK"."ID" = T4."BOOK_ID") GROUP BY "AGGREGATION_AUTHOR"."ID") subquery;
SELECT MAX(CASE WHEN ("AUTHORS_HAVE_OTHER_BOOKS" = FALSE AND "HAS_AUTHORS" = TRUE) THEN "__COL1" ELSE NULL END) FROM (SELECT "AGGREGATION_BOOK"."PUBLISHER_ID" AS "PUBLISHER", ((SELECT (1) AS "A" FROM "AGGREGATION_BOOK_AUTHORS" U0 WHERE U0."BOOK_ID" = ("AGGREGATION_BOOK"."ID") FETCH FIRST 1 ROWS ONLY) IS NOT NULL) AS "HAS_AUTHORS", ((SELECT (1) AS "A" FROM "AGGREGATION_BOOK" V0 INNER JOIN "AGGREGATION_BOOK_AUTHORS" V1 ON (V0."ID" = V1."BOOK_ID") WHERE (V1."AUTHOR_ID" IN (SELECT U0."ID" FROM "AGGREGATION_AUTHOR" U0 INNER JOIN "AGGREGATION_BOOK" U1 ON (U0."ID" = U1."CONTACT_ID") WHERE U1."ID" = ("AGGREGATION_BOOK"."ID")) AND NOT (V0."ID" = ("AGGREGATION_BOOK"."ID"))) FETCH FIRST 1 ROWS ONLY) IS NOT NULL) AS "AUTHORS_HAVE_OTHER_BOOKS", "AGGREGATION_BOOK"."RATING" AS "__COL1" FROM "AGGREGATION_BOOK") subquery;
SELECT MAX("BOOKS_PER_RATING") FROM (SELECT "AGGREGATION_BOOK"."RATING" AS "RATING", (COUNT("AGGREGATION_BOOK"."ID") + CAST(%s AS INTEGER)) AS "BOOKS_PER_RATING" FROM "AGGREGATION_BOOK" GROUP BY "AGGREGATION_BOOK"."RATING") subquery;
SELECT MAX("BOOKS_PER_RATING") FROM (SELECT "AGGREGATION_BOOK"."RATING" AS "RATING", COUNT("AGGREGATION_BOOK"."ID") AS "BOOKS_PER_RATING" FROM "AGGREGATION_BOOK" GROUP BY "AGGREGATION_BOOK"."RATING") subquery;
SELECT MAX("COMBINED_AGES") FROM (SELECT SUM(("AGGREGATION_AUTHOR"."AGE" + T3."AGE")) AS "COMBINED_AGES" FROM "AGGREGATION_AUTHOR" LEFT OUTER JOIN "AGGREGATION_AUTHOR_FRIENDS" ON ("AGGREGATION_AUTHOR"."ID" = "AGGREGATION_AUTHOR_FRIENDS"."FROM_AUTHOR_ID") LEFT OUTER JOIN "AGGREGATION_AUTHOR" T3 ON ("AGGREGATION_AUTHOR_FRIENDS"."TO_AUTHOR_ID" = T3."ID") GROUP BY "AGGREGATION_AUTHOR"."ID") subquery;
SELECT SUM(CASE WHEN "TOTAL_PAGES" >= %s THEN "__COL1" ELSE NULL END) FROM (SELECT SUM(CASE WHEN "AGGREGATION_BOOK"."RATING" > %s THEN "AGGREGATION_BOOK"."PAGES" ELSE NULL END) AS "TOTAL_PAGES", "AGGREGATION_AUTHOR"."AGE" AS "__COL1" FROM "AGGREGATION_AUTHOR" LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" ON ("AGGREGATION_AUTHOR"."ID" = "AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID") LEFT OUTER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_BOOK_AUTHORS"."BOOK_ID" = "AGGREGATION_BOOK"."ID") GROUP BY "AGGREGATION_AUTHOR"."ID", "AGGREGATION_AUTHOR"."AGE") subquery;
SELECT SUM("COUNT") FROM (SELECT (SELECT COUNT(CASE WHEN (U0."PAGES" = ("AGGREGATION_AUTHOR"."AGE")) THEN U0."ID" ELSE NULL END) AS "WEIRD_COUNT" FROM "AGGREGATION_BOOK" U0 GROUP BY U0."ID", U0."ISBN", U0."NAME", U0."PAGES", U0."RATING", U0."PRICE", U0."CONTACT_ID", U0."PUBLISHER_ID", U0."PUBDATE" FETCH FIRST 1 ROWS ONLY) AS "COUNT" FROM "AGGREGATION_AUTHOR") subquery;
SELECT SUM("TOTAL_BOOKS") FROM (SELECT "AGGREGATION_AUTHOR"."ID" AS "PK", (SELECT COUNT(U0."BOOK_ID") AS "TOTAL" FROM "AGGREGATION_BOOK_AUTHORS" U0 WHERE U0."AUTHOR_ID" = ("AGGREGATION_AUTHOR"."ID") GROUP BY U0."AUTHOR_ID") AS "TOTAL_BOOKS" FROM "AGGREGATION_AUTHOR") subquery;
SELECT SUM("TOTAL_BOOKS_REF") FROM (SELECT "AGGREGATION_AUTHOR"."ID" AS "PK", ((SELECT COUNT(U0."BOOK_ID") AS "TOTAL" FROM "AGGREGATION_BOOK_AUTHORS" U0 WHERE U0."AUTHOR_ID" = ("AGGREGATION_AUTHOR"."ID") GROUP BY U0."AUTHOR_ID") / CAST(%s AS INTEGER)) AS "TOTAL_BOOKS_REF" FROM "AGGREGATION_AUTHOR") subquery;
SELECT SUM("__COL1") FROM (SELECT DISTINCT "AGGREGATION_AUTHOR"."ID" AS "COL1", "AGGREGATION_AUTHOR"."NAME" AS "COL2", "AGGREGATION_AUTHOR"."AGE" AS "COL3", "AGGREGATION_AUTHOR"."RATING" AS "COL4", "AGGREGATION_AUTHOR"."AGE" AS "__COL1" FROM "AGGREGATION_AUTHOR" INNER JOIN "AGGREGATION_BOOK_AUTHORS" ON ("AGGREGATION_AUTHOR"."ID" = "AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID") WHERE "AGGREGATION_BOOK_AUTHORS"."BOOK_ID" IN (%s, %s)) subquery;
SELECT SUM("__COL1") FROM (SELECT "AGGREGATION_PUBLISHER"."NUM_AWARDS" AS "__COL1" FROM "AGGREGATION_PUBLISHER" LEFT OUTER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_PUBLISHER"."ID" = "AGGREGATION_BOOK"."PUBLISHER_ID") GROUP BY "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NUM_AWARDS") subquery;
SELECT ((AVG("AGGREGATION_BOOK"."PRICE") + CAST(%s AS INTEGER)) * CAST(%s AS INTEGER)) AS "AVG_PRICE" FROM "AGGREGATION_BOOK" WHERE "AGGREGATION_BOOK"."RATING" = %s;
SELECT (ANY_VALUE("DJDB2I_GROUPING"."G1") / CAST(COUNT("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID") AS DOUBLE)) AS "PAGES_PER_AUTHOR" FROM "AGGREGATION_BOOK" LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" ON ("AGGREGATION_BOOK"."ID" = "AGGREGATION_BOOK_AUTHORS"."BOOK_ID") CROSS JOIN LATERAL (SELECT GREATEST("AGGREGATION_BOOK"."PAGES", CAST(%s AS INTEGER)) AS "G1" FROM SYSIBM.SYSDUMMY1) AS "DJDB2I_GROUPING" GROUP BY "DJDB2I_GROUPING"."G1" ORDER BY 1 ASC FETCH FIRST 1 ROWS ONLY;
SELECT (ANY_VALUE("DJDB2I_GROUPING"."G1") / CAST(COUNT("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID") AS DOUBLE)) AS "PAGES_PER_AUTHOR" FROM "AGGREGATION_BOOK" LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" ON ("AGGREGATION_BOOK"."ID" = "AGGREGATION_BOOK_AUTHORS"."BOOK_ID") CROSS JOIN LATERAL (SELECT GREATEST("AGGREGATION_BOOK"."PAGES", CAST(%s AS INTEGER)) AS "G1" FROM SYSIBM.SYSDUMMY1) AS "DJDB2I_GROUPING" GROUP BY "DJDB2I_GROUPING"."G1" ORDER BY 1 ASC OFFSET 1 ROWS FETCH FIRST 1 ROWS ONLY;
SELECT (ANY_VALUE("DJDB2I_GROUPING"."G1") / CAST(COUNT("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID") AS DOUBLE)) AS "PAGES_PER_AUTHOR" FROM "AGGREGATION_BOOK" LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" ON ("AGGREGATION_BOOK"."ID" = "AGGREGATION_BOOK_AUTHORS"."BOOK_ID") CROSS JOIN LATERAL (SELECT GREATEST("AGGREGATION_BOOK"."PAGES", CAST(%s AS INTEGER)) AS "G1" FROM SYSIBM.SYSDUMMY1) AS "DJDB2I_GROUPING" GROUP BY "DJDB2I_GROUPING"."G1" ORDER BY 1 ASC OFFSET 2 ROWS FETCH FIRST 1 ROWS ONLY;
SELECT (AVG("AGGREGATION_BOOK"."PRICE") + CAST(%s AS INTEGER)) AS "AVG_PRICE" FROM "AGGREGATION_BOOK" WHERE "AGGREGATION_BOOK"."RATING" = %s;
SELECT (MAX("AGGREGATION_BOOK"."RATING") + MAX("AGGREGATION_BOOK"."RATING")) AS "DOUBLE_MAX_RATING" FROM "AGGREGATION_BOOK";
SELECT (SELECT CASE WHEN COUNT(CASE WHEN NOT (U2."NAME" LIKE %s ESCAPE '\' AND U2."NAME" IS NOT NULL) THEN U2."NAME" ELSE NULL END) = 0 THEN NULL ELSE LISTAGG(CASE WHEN NOT (U2."NAME" LIKE %s ESCAPE '\' AND U2."NAME" IS NOT NULL) THEN CAST(U2."NAME" AS NCLOB) ELSE NULL END, CAST(%s AS NVARCHAR(32))) END AS "AGG" FROM "AGGREGATION_BOOK" U0 LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" U1 ON (U0."ID" = U1."BOOK_ID") LEFT OUTER JOIN "AGGREGATION_AUTHOR" U2 ON (U1."AUTHOR_ID" = U2."ID") WHERE U0."ID" = ("AGGREGATION_BOOK"."ID") GROUP BY U0."ID", U0."ISBN", U0."NAME", U0."PAGES", U0."RATING", U0."PRICE", U0."CONTACT_ID", U0."PUBLISHER_ID", U0."PUBDATE") AS "AGG" FROM "AGGREGATION_BOOK";
SELECT (SELECT CASE WHEN COUNT(U0."NAME") = 0 THEN NULL ELSE LISTAGG(CAST(U0."NAME" AS NCLOB), CAST(%s AS NVARCHAR(32))) WITHIN GROUP ( ORDER BY "AGGREGATION_PUBLISHER"."NUM_AWARDS") END AS "STRINGAGG" FROM "AGGREGATION_BOOK" U0 GROUP BY U0."ID", U0."ISBN", U0."NAME", U0."PAGES", U0."RATING", U0."PRICE", U0."CONTACT_ID", U0."PUBLISHER_ID", U0."PUBDATE" FETCH FIRST 1 ROWS ONLY) AS "STRINGAGG" FROM "AGGREGATION_PUBLISHER" ORDER BY "AGGREGATION_PUBLISHER"."ID" ASC;
SELECT (SELECT CASE WHEN COUNT(U2."NAME") = 0 THEN NULL ELSE LISTAGG(CAST(U2."NAME" AS NCLOB), CAST(%s AS NVARCHAR(32))) WITHIN GROUP ( ORDER BY U2."NAME") END AS "AGG" FROM "AGGREGATION_BOOK" U0 LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" U1 ON (U0."ID" = U1."BOOK_ID") LEFT OUTER JOIN "AGGREGATION_AUTHOR" U2 ON (U1."AUTHOR_ID" = U2."ID") WHERE U0."ID" = ("AGGREGATION_BOOK"."ID") GROUP BY U0."ID", U0."ISBN", U0."NAME", U0."PAGES", U0."RATING", U0."PRICE", U0."CONTACT_ID", U0."PUBLISHER_ID", U0."PUBDATE") AS "AGG" FROM "AGGREGATION_BOOK" ORDER BY 1 ASC;
SELECT (SELECT COUNT(V0."ID") AS "PUBLISHER_COUNT" FROM "AGGREGATION_PUBLISHER" V0 WHERE V0."ID" IN (SELECT U0."ID" AS "ID" FROM "AGGREGATION_PUBLISHER" U0 WHERE U0."NAME" = ("AGGREGATION_PUBLISHER"."NAME")) GROUP BY V0."ID", V0."NAME", V0."NUM_AWARDS", V0."DURATION" FETCH FIRST 1 ROWS ONLY) AS "PUBLISHER_COUNT" FROM "AGGREGATION_BOOK" INNER JOIN "AGGREGATION_PUBLISHER" ON ("AGGREGATION_BOOK"."PUBLISHER_ID" = "AGGREGATION_PUBLISHER"."ID") LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" ON ("AGGREGATION_BOOK"."ID" = "AGGREGATION_BOOK_AUTHORS"."BOOK_ID") GROUP BY "AGGREGATION_BOOK"."ID", "AGGREGATION_BOOK"."ISBN", "AGGREGATION_BOOK"."NAME", "AGGREGATION_BOOK"."PAGES", "AGGREGATION_BOOK"."RATING", "AGGREGATION_BOOK"."PRICE", "AGGREGATION_BOOK"."CONTACT_ID", "AGGREGATION_BOOK"."PUBLISHER_ID", "AGGREGATION_BOOK"."PUBDATE", (SELECT COUNT(V0."ID") AS "PUBLISHER_COUNT" FROM "AGGREGATION_PUBLISHER" V0 WHERE V0."ID" IN (SELECT U0."ID" AS "ID" FROM "AGGREGATION_PUBLISHER" U0 WHERE U0."NAME" = ("AGGREGATION_PUBLISHER"."NAME")) GROUP BY V0."ID", V0."NAME", V0."NUM_AWARDS", V0."DURATION" FETCH FIRST 1 ROWS ONLY);
SELECT (SELECT U0."RATING" AS "RATING" FROM "AGGREGATION_BOOK" U0 WHERE U0."ID" = ("AGGREGATION_BOOK"."ID")) AS "RATING", COUNT(*) AS "TOTAL_COUNT" FROM "AGGREGATION_PUBLISHER" INNER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_PUBLISHER"."ID" = "AGGREGATION_BOOK"."PUBLISHER_ID") INNER JOIN "AGGREGATION_AUTHOR" ON ("AGGREGATION_BOOK"."CONTACT_ID" = "AGGREGATION_AUTHOR"."ID") WHERE "AGGREGATION_AUTHOR"."AGE" > %s GROUP BY (SELECT U0."RATING" AS "RATING" FROM "AGGREGATION_BOOK" U0 WHERE U0."ID" = ("AGGREGATION_BOOK"."ID")) ORDER BY 1 ASC;
SELECT (SUM("AGGREGATION_AUTHOR"."AGE") / COUNT(*)) AS "AV_AGE" FROM "AGGREGATION_AUTHOR";
SELECT (SUM("AGGREGATION_AUTHOR"."AGE") / COUNT("AGGREGATION_AUTHOR"."AGE")) AS "AV_AGE" FROM "AGGREGATION_AUTHOR";
SELECT ANY_VALUE(CASE WHEN "AGGREGATION_BOOK"."RATING" <= %s THEN YEAR("AGGREGATION_BOOK"."PUBDATE") ELSE NULL END) AS "PUBDATE_YEAR" FROM "AGGREGATION_BOOK" CROSS JOIN LATERAL (SELECT GREATEST("AGGREGATION_BOOK"."PAGES", CAST(%s AS INTEGER)) AS "G1" FROM SYSIBM.SYSDUMMY1) AS "DJDB2I_GROUPING" GROUP BY "DJDB2I_GROUPING"."G1";
SELECT ANY_VALUE(YEAR("AGGREGATION_BOOK"."PUBDATE")) AS "PUBDATE_YEAR" FROM "AGGREGATION_BOOK" CROSS JOIN LATERAL (SELECT GREATEST("AGGREGATION_BOOK"."PAGES", CAST(%s AS INTEGER)) AS "G1" FROM SYSIBM.SYSDUMMY1) AS "DJDB2I_GROUPING" GROUP BY "DJDB2I_GROUPING"."G1" ORDER BY 1 ASC FETCH FIRST 2 ROWS ONLY;
SELECT ANY_VALUE(YEAR("AGGREGATION_BOOK"."PUBDATE")) AS "PUBDATE_YEAR" FROM "AGGREGATION_BOOK" CROSS JOIN LATERAL (SELECT GREATEST("AGGREGATION_BOOK"."PAGES", CAST(%s AS INTEGER)) AS "G1" FROM SYSIBM.SYSDUMMY1) AS "DJDB2I_GROUPING" GROUP BY "DJDB2I_GROUPING"."G1" ORDER BY 1 ASC OFFSET 2 ROWS FETCH FIRST 1 ROWS ONLY;
SELECT AVG(CASE WHEN "AGGREGATION_AUTHOR"."NAME" LIKE %s ESCAPE '\' THEN CAST("AGGREGATION_AUTHOR"."AGE" AS DOUBLE) ELSE NULL END) AS "AGE" FROM "AGGREGATION_AUTHOR";
SELECT AVG(CAST(T3."AGE" AS DOUBLE)) AS "FRIENDS__AGE__AVG" FROM "AGGREGATION_AUTHOR" LEFT OUTER JOIN "AGGREGATION_AUTHOR_FRIENDS" ON ("AGGREGATION_AUTHOR"."ID" = "AGGREGATION_AUTHOR_FRIENDS"."FROM_AUTHOR_ID") LEFT OUTER JOIN "AGGREGATION_AUTHOR" T3 ON ("AGGREGATION_AUTHOR_FRIENDS"."TO_AUTHOR_ID" = T3."ID");
SELECT AVG(CAST("AGGREGATION_AUTHOR"."AGE" AS DOUBLE)) AS "AGE__AVG" FROM "AGGREGATION_AUTHOR";
SELECT AVG(CAST("AGGREGATION_AUTHOR"."AGE" AS DOUBLE)) AS "AUTHORS__AGE__AVG" FROM "AGGREGATION_BOOK" LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" ON ("AGGREGATION_BOOK"."ID" = "AGGREGATION_BOOK_AUTHORS"."BOOK_ID") LEFT OUTER JOIN "AGGREGATION_AUTHOR" ON ("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" = "AGGREGATION_AUTHOR"."ID") WHERE "AGGREGATION_BOOK"."RATING" < %s;
SELECT AVG(CAST("AGGREGATION_AUTHOR"."AGE" AS DOUBLE)) AS "AV_AGE" FROM "AGGREGATION_AUTHOR";
SELECT AVG(CAST("AGGREGATION_AUTHOR"."AGE" AS DOUBLE)) AS "MEAN_AGE" FROM "AGGREGATION_BOOK" LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" ON ("AGGREGATION_BOOK"."ID" = "AGGREGATION_BOOK_AUTHORS"."BOOK_ID") LEFT OUTER JOIN "AGGREGATION_AUTHOR" ON ("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" = "AGGREGATION_AUTHOR"."ID") WHERE "AGGREGATION_BOOK"."ID" = %s GROUP BY "AGGREGATION_BOOK"."ID", "AGGREGATION_BOOK"."ISBN", "AGGREGATION_BOOK"."NAME", "AGGREGATION_BOOK"."PAGES", "AGGREGATION_BOOK"."RATING", "AGGREGATION_BOOK"."PRICE", "AGGREGATION_BOOK"."CONTACT_ID", "AGGREGATION_BOOK"."PUBLISHER_ID", "AGGREGATION_BOOK"."PUBDATE";
