SELECT CASE WHEN COUNT("AGGREGATION_PUBLISHER"."NAME") = 0 THEN NULL ELSE LISTAGG(CAST("AGGREGATION_PUBLISHER"."NAME" AS NCLOB), CAST(%s AS NVARCHAR(32))) END AS "STRINGAGG" FROM "AGGREGATION_PUBLISHER";
