SELECT CASE WHEN COUNT("AGGREGATION_STORE"."NAME") = 0 THEN NULL ELSE LISTAGG(CAST("AGGREGATION_STORE"."NAME" AS NCLOB), CAST(%s AS NVARCHAR(32))) WITHIN GROUP ( ORDER BY "AGGREGATION_STORE"."ORIGINAL_OPENING" ASC) END AS "STRINGAGG" FROM "AGGREGATION_STORE";
SELECT CASE WHEN COUNT("AGGREGATION_STORE"."NAME") = 0 THEN NULL ELSE LISTAGG(CAST("AGGREGATION_STORE"."NAME" AS NCLOB), CAST(%s AS NVARCHAR(32))) WITHIN GROUP ( ORDER BY "AGGREGATION_STORE"."ORIGINAL_OPENING" DESC) END AS "STRINGAGG" FROM "AGGREGATION_STORE";
SELECT CASE WHEN COUNT("AGGREGATION_STORE"."NAME") = 0 THEN NULL ELSE LISTAGG(CAST("AGGREGATION_STORE"."NAME" AS NCLOB), CAST(%s AS NVARCHAR(32))) WITHIN GROUP ( ORDER BY "AGGREGATION_STORE"."ORIGINAL_OPENING") END AS "STRINGAGG" FROM "AGGREGATION_STORE";
