SELECT DISTINCT DATE(TRUNC_TIMESTAMP("AGGREGATION_BOOK"."PUBDATE", 'YEAR')) AS "DATEFIELD" FROM "AGGREGATION_BOOK" LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" ON ("AGGREGATION_BOOK"."ID" = "AGGREGATION_BOOK_AUTHORS"."BOOK_ID") WHERE "AGGREGATION_BOOK"."PUBDATE" IS NOT NULL GROUP BY "AGGREGATION_BOOK"."ID", "AGGREGATION_BOOK"."ISBN", "AGGREGATION_BOOK"."NAME", "AGGREGATION_BOOK"."PAGES", "AGGREGATION_BOOK"."RATING", "AGGREGATION_BOOK"."PRICE", "AGGREGATION_BOOK"."CONTACT_ID", "AGGREGATION_BOOK"."PUBLISHER_ID", "AGGREGATION_BOOK"."PUBDATE", DATE(TRUNC_TIMESTAMP("AGGREGATION_BOOK"."PUBDATE", 'YEAR')) ORDER BY 1 ASC;
