SELECT MAX(CASE WHEN ((SELECT (1) AS "A" FROM "AGGREGATION_BOOK_AUTHORS" U0 WHERE U0."BOOK_ID" = ("AGGREGATION_BOOK"."ID") FETCH FIRST 1 ROWS ONLY) IS NOT NULL) THEN "AGGREGATION_BOOK"."RATING" ELSE NULL END) AS "MAX_RATING" FROM "AGGREGATION_BOOK";
