SELECT "AGGREGATION_AUTHOR"."ID", "AGGREGATION_AUTHOR"."NAME", "AGGREGATION_AUTHOR"."AGE", "AGGREGATION_AUTHOR"."RATING" FROM "AGGREGATION_AUTHOR" WHERE "AGGREGATION_AUTHOR"."NAME" LIKE %s ESCAPE '\' FETCH FIRST 21 ROWS ONLY;
