SELECT "AGGREGATION_AUTHOR"."ID", "AGGREGATION_AUTHOR"."NAME", "AGGREGATION_AUTHOR"."AGE", "AGGREGATION_AUTHOR"."RATING", (SUM("AGGREGATION_AUTHOR"."AGE") + SUM(T3."AGE")) AS "COMBINED_AGES" FROM "AGGREGATION_AUTHOR" LEFT OUTER JOIN "AGGREGATION_AUTHOR_FRIENDS" ON ("AGGREGATION_AUTHOR"."ID" = "AGGREGATION_AUTHOR_FRIENDS"."FROM_AUTHOR_ID") LEFT OUTER JOIN "AGGREGATION_AUTHOR" T3 ON ("AGGREGATION_AUTHOR_FRIENDS"."TO_AUTHOR_ID" = T3."ID") GROUP BY "AGGREGATION_AUTHOR"."ID", "AGGREGATION_AUTHOR"."NAME", "AGGREGATION_AUTHOR"."AGE", "AGGREGATION_AUTHOR"."RATING" ORDER BY "AGGREGATION_AUTHOR"."NAME" ASC;
