SELECT "AGGREGATION_AUTHOR"."ID", "AGGREGATION_AUTHOR"."NAME", "AGGREGATION_AUTHOR"."AGE", "AGGREGATION_AUTHOR"."RATING", COUNT(CASE WHEN T3."AGE" > ("AGGREGATION_AUTHOR"."AGE") THEN "AGGREGATION_AUTHOR_FRIENDS"."TO_AUTHOR_ID" ELSE NULL END) AS "OLDER_FRIENDS_COUNT" FROM "AGGREGATION_AUTHOR" LEFT OUTER JOIN "AGGREGATION_AUTHOR_FRIENDS" ON ("AGGREGATION_AUTHOR"."ID" = "AGGREGATION_AUTHOR_FRIENDS"."FROM_AUTHOR_ID") LEFT OUTER JOIN "AGGREGATION_AUTHOR" T3 ON ("AGGREGATION_AUTHOR_FRIENDS"."TO_AUTHOR_ID" = T3."ID") WHERE "AGGREGATION_AUTHOR"."ID" IN (SELECT U0."ID" AS "PK" FROM "AGGREGATION_AUTHOR" U0 LEFT OUTER JOIN "AGGREGATION_AUTHOR_FRIENDS" U1 ON (U0."ID" = U1."FROM_AUTHOR_ID") LEFT OUTER JOIN "AGGREGATION_AUTHOR" U2 ON (U1."TO_AUTHOR_ID" = U2."ID") GROUP BY U0."ID", U0."NAME", U0."AGE", U0."RATING" HAVING COUNT(CASE WHEN (U2."AGE" > (U0."AGE")) THEN U1."TO_AUTHOR_ID" ELSE NULL END) >= %s) GROUP BY "AGGREGATION_AUTHOR"."ID", "AGGREGATION_AUTHOR"."NAME", "AGGREGATION_AUTHOR"."AGE", "AGGREGATION_AUTHOR"."RATING" HAVING COUNT(CASE WHEN (T3."AGE" > ("AGGREGATION_AUTHOR"."AGE")) THEN "AGGREGATION_AUTHOR_FRIENDS"."TO_AUTHOR_ID" ELSE NULL END) >= %s FETCH FIRST 21 ROWS ONLY;
SELECT "AGGREGATION_AUTHOR"."ID", "AGGREGATION_AUTHOR"."NAME", "AGGREGATION_AUTHOR"."AGE", "AGGREGATION_AUTHOR"."RATING", COUNT(DISTINCT "AGGREGATION_AUTHOR_FRIENDS"."TO_AUTHOR_ID") AS "NUM_FRIENDS" FROM "AGGREGATION_AUTHOR" LEFT OUTER JOIN "AGGREGATION_AUTHOR_FRIENDS" ON ("AGGREGATION_AUTHOR"."ID" = "AGGREGATION_AUTHOR_FRIENDS"."FROM_AUTHOR_ID") GROUP BY "AGGREGATION_AUTHOR"."ID", "AGGREGATION_AUTHOR"."NAME", "AGGREGATION_AUTHOR"."AGE", "AGGREGATION_AUTHOR"."RATING" HAVING COUNT(DISTINCT "AGGREGATION_AUTHOR_FRIENDS"."TO_AUTHOR_ID") = %s ORDER BY "AGGREGATION_AUTHOR"."ID" ASC;
