SELECT "AGGREGATION_BOOK"."ID", "AGGREGATION_BOOK"."ISBN", "AGGREGATION_BOOK"."NAME", "AGGREGATION_BOOK"."PAGES", "AGGREGATION_BOOK"."RATING", "AGGREGATION_BOOK"."PRICE", "AGGREGATION_BOOK"."CONTACT_ID", "AGGREGATION_BOOK"."PUBLISHER_ID", "AGGREGATION_BOOK"."PUBDATE", AVG(CAST(T5."AGE" AS DOUBLE)) AS "MEAN_AGE" FROM "AGGREGATION_BOOK" LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" ON ("AGGREGATION_BOOK"."ID" = "AGGREGATION_BOOK_AUTHORS"."BOOK_ID") LEFT OUTER JOIN "AGGREGATION_AUTHOR" T5 ON ("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" = T5."ID") WHERE "AGGREGATION_BOOK"."ID" = %s GROUP BY "AGGREGATION_BOOK"."ID", "AGGREGATION_BOOK"."ISBN", "AGGREGATION_BOOK"."NAME", "AGGREGATION_BOOK"."PAGES", "AGGREGATION_BOOK"."RATING", "AGGREGATION_BOOK"."PRICE", "AGGREGATION_BOOK"."CONTACT_ID", "AGGREGATION_BOOK"."PUBLISHER_ID", "AGGREGATION_BOOK"."PUBDATE";
