SELECT "AGGREGATION_BOOK"."ISBN" AS "ISBN", COALESCE(MIN(CASE WHEN NOT ("AGGREGATION_STORE"."NAME" = %s AND "AGGREGATION_STORE"."NAME" IS NOT NULL) THEN "AGGREGATION_STORE"."FRIDAY_NIGHT_CLOSING" ELSE NULL END), CAST(%s AS TIME)) AS "OLDEST_STORE_OPENING" FROM "AGGREGATION_BOOK" LEFT OUTER JOIN "AGGREGATION_STORE_BOOKS" ON ("AGGREGATION_BOOK"."ID" = "AGGREGATION_STORE_BOOKS"."BOOK_ID") LEFT OUTER JOIN "AGGREGATION_STORE" ON ("AGGREGATION_STORE_BOOKS"."STORE_ID" = "AGGREGATION_STORE"."ID") GROUP BY "AGGREGATION_BOOK"."ID", "AGGREGATION_BOOK"."ISBN", "AGGREGATION_BOOK"."NAME", "AGGREGATION_BOOK"."PAGES", "AGGREGATION_BOOK"."RATING", "AGGREGATION_BOOK"."PRICE", "AGGREGATION_BOOK"."CONTACT_ID", "AGGREGATION_BOOK"."PUBLISHER_ID", "AGGREGATION_BOOK"."PUBDATE" ORDER BY 1 ASC;
SELECT "AGGREGATION_BOOK"."ISBN" AS "ISBN", COALESCE(MIN(CASE WHEN NOT ("AGGREGATION_STORE"."NAME" = %s AND "AGGREGATION_STORE"."NAME" IS NOT NULL) THEN "AGGREGATION_STORE"."FRIDAY_NIGHT_CLOSING" ELSE NULL END), "DJDB2I_GROUPING"."G1") AS "OLDEST_STORE_OPENING" FROM "AGGREGATION_BOOK" LEFT OUTER JOIN "AGGREGATION_STORE_BOOKS" ON ("AGGREGATION_BOOK"."ID" = "AGGREGATION_STORE_BOOKS"."BOOK_ID") LEFT OUTER JOIN "AGGREGATION_STORE" ON ("AGGREGATION_STORE_BOOKS"."STORE_ID" = "AGGREGATION_STORE"."ID") CROSS JOIN LATERAL (SELECT TIME(TRUNC_TIMESTAMP(TIMESTAMP(DATE('0001-01-01'), TIME(CURRENT_TIMESTAMP)), 'HH')) AS "G1" FROM SYSIBM.SYSDUMMY1) AS "DJDB2I_GROUPING" GROUP BY "AGGREGATION_BOOK"."ID", "AGGREGATION_BOOK"."ISBN", "AGGREGATION_BOOK"."NAME", "AGGREGATION_BOOK"."PAGES", "AGGREGATION_BOOK"."RATING", "AGGREGATION_BOOK"."PRICE", "AGGREGATION_BOOK"."CONTACT_ID", "AGGREGATION_BOOK"."PUBLISHER_ID", "AGGREGATION_BOOK"."PUBDATE", "DJDB2I_GROUPING"."G1" ORDER BY 1 ASC;
SELECT "AGGREGATION_BOOK"."ISBN" AS "ISBN", COALESCE(MIN(CASE WHEN NOT ("AGGREGATION_STORE"."NAME" = %s AND "AGGREGATION_STORE"."NAME" IS NOT NULL) THEN "AGGREGATION_STORE"."ORIGINAL_OPENING" ELSE NULL END), CAST(%s AS TIMESTAMP(6))) AS "OLDEST_STORE_OPENING" FROM "AGGREGATION_BOOK" LEFT OUTER JOIN "AGGREGATION_STORE_BOOKS" ON ("AGGREGATION_BOOK"."ID" = "AGGREGATION_STORE_BOOKS"."BOOK_ID") LEFT OUTER JOIN "AGGREGATION_STORE" ON ("AGGREGATION_STORE_BOOKS"."STORE_ID" = "AGGREGATION_STORE"."ID") GROUP BY "AGGREGATION_BOOK"."ID", "AGGREGATION_BOOK"."ISBN", "AGGREGATION_BOOK"."NAME", "AGGREGATION_BOOK"."PAGES", "AGGREGATION_BOOK"."RATING", "AGGREGATION_BOOK"."PRICE", "AGGREGATION_BOOK"."CONTACT_ID", "AGGREGATION_BOOK"."PUBLISHER_ID", "AGGREGATION_BOOK"."PUBDATE" ORDER BY 1 ASC;
SELECT "AGGREGATION_BOOK"."ISBN" AS "ISBN", COALESCE(MIN(CASE WHEN NOT ("AGGREGATION_STORE"."NAME" = %s AND "AGGREGATION_STORE"."NAME" IS NOT NULL) THEN "AGGREGATION_STORE"."ORIGINAL_OPENING" ELSE NULL END), "DJDB2I_GROUPING"."G1") AS "OLDEST_STORE_OPENING" FROM "AGGREGATION_BOOK" LEFT OUTER JOIN "AGGREGATION_STORE_BOOKS" ON ("AGGREGATION_BOOK"."ID" = "AGGREGATION_STORE_BOOKS"."BOOK_ID") LEFT OUTER JOIN "AGGREGATION_STORE" ON ("AGGREGATION_STORE_BOOKS"."STORE_ID" = "AGGREGATION_STORE"."ID") CROSS JOIN LATERAL (SELECT TRUNC_TIMESTAMP(CURRENT_TIMESTAMP, 'HH') AS "G1" FROM SYSIBM.SYSDUMMY1) AS "DJDB2I_GROUPING" GROUP BY "AGGREGATION_BOOK"."ID", "AGGREGATION_BOOK"."ISBN", "AGGREGATION_BOOK"."NAME", "AGGREGATION_BOOK"."PAGES", "AGGREGATION_BOOK"."RATING", "AGGREGATION_BOOK"."PRICE", "AGGREGATION_BOOK"."CONTACT_ID", "AGGREGATION_BOOK"."PUBLISHER_ID", "AGGREGATION_BOOK"."PUBDATE", "DJDB2I_GROUPING"."G1" ORDER BY 1 ASC;
SELECT "AGGREGATION_BOOK"."NAME" AS "NAME" FROM "AGGREGATION_BOOK" LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" ON ("AGGREGATION_BOOK"."ID" = "AGGREGATION_BOOK_AUTHORS"."BOOK_ID") LEFT OUTER JOIN "AGGREGATION_AUTHOR" ON ("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" = "AGGREGATION_AUTHOR"."ID") WHERE "AGGREGATION_BOOK"."ID" = %s GROUP BY "AGGREGATION_BOOK"."ID", "AGGREGATION_BOOK"."ISBN", "AGGREGATION_BOOK"."NAME", "AGGREGATION_BOOK"."PAGES", "AGGREGATION_BOOK"."RATING", "AGGREGATION_BOOK"."PRICE", "AGGREGATION_BOOK"."CONTACT_ID", "AGGREGATION_BOOK"."PUBLISHER_ID", "AGGREGATION_BOOK"."PUBDATE";
SELECT "AGGREGATION_BOOK"."NAME" AS "NAME", MIN(T4."AGE") AS "MIN_AGE" FROM "AGGREGATION_BOOK" INNER JOIN "AGGREGATION_AUTHOR" ON ("AGGREGATION_BOOK"."CONTACT_ID" = "AGGREGATION_AUTHOR"."ID") LEFT OUTER JOIN "AGGREGATION_AUTHOR_FRIENDS" ON ("AGGREGATION_AUTHOR"."ID" = "AGGREGATION_AUTHOR_FRIENDS"."FROM_AUTHOR_ID") LEFT OUTER JOIN "AGGREGATION_AUTHOR" T4 ON ("AGGREGATION_AUTHOR_FRIENDS"."TO_AUTHOR_ID" = T4."ID") WHERE ((SELECT U0."ID" AS "ID" FROM "AGGREGATION_AUTHOR" U0 WHERE U0."AGE" = (T4."AGE") ORDER BY U0."AGE" ASC FETCH FIRST 1 ROWS ONLY) IS NOT NULL AND "AGGREGATION_BOOK"."PUBLISHER_ID" = %s) GROUP BY "AGGREGATION_BOOK"."ID", "AGGREGATION_BOOK"."ISBN", "AGGREGATION_BOOK"."NAME", "AGGREGATION_BOOK"."PAGES", "AGGREGATION_BOOK"."RATING", "AGGREGATION_BOOK"."PRICE", "AGGREGATION_BOOK"."CONTACT_ID", "AGGREGATION_BOOK"."PUBLISHER_ID", "AGGREGATION_BOOK"."PUBDATE" ORDER BY 1 ASC;
SELECT "AGGREGATION_BOOK"."PRICE" AS "PRICE", COUNT("AGGREGATION_BOOK"."PRICE") AS "COUNT" FROM "AGGREGATION_BOOK" GROUP BY "AGGREGATION_BOOK"."PRICE" ORDER BY 2 DESC, 1 ASC;
SELECT "AGGREGATION_BOOK"."RATING" AS "RATING", COUNT("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID") AS "N_AUTHORS", AVG(CAST("AGGREGATION_AUTHOR"."AGE" AS DOUBLE)) AS "MEAN_AGE" FROM "AGGREGATION_BOOK" LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" ON ("AGGREGATION_BOOK"."ID" = "AGGREGATION_BOOK_AUTHORS"."BOOK_ID") LEFT OUTER JOIN "AGGREGATION_AUTHOR" ON ("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" = "AGGREGATION_AUTHOR"."ID") GROUP BY "AGGREGATION_BOOK"."RATING" ORDER BY 1 ASC;
SELECT "AGGREGATION_BOOK"."RATING" AS "RATING", MAX("AGGREGATION_AUTHOR"."AGE") AS "OLDEST" FROM "AGGREGATION_BOOK" LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" ON ("AGGREGATION_BOOK"."ID" = "AGGREGATION_BOOK_AUTHORS"."BOOK_ID") LEFT OUTER JOIN "AGGREGATION_AUTHOR" ON ("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" = "AGGREGATION_AUTHOR"."ID") GROUP BY "AGGREGATION_BOOK"."RATING" ORDER BY 2 ASC, 1 ASC;
SELECT "AGGREGATION_BOOK"."RATING" AS "RATING", MAX("AGGREGATION_AUTHOR"."AGE") AS "OLDEST" FROM "AGGREGATION_BOOK" LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" ON ("AGGREGATION_BOOK"."ID" = "AGGREGATION_BOOK_AUTHORS"."BOOK_ID") LEFT OUTER JOIN "AGGREGATION_AUTHOR" ON ("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" = "AGGREGATION_AUTHOR"."ID") GROUP BY "AGGREGATION_BOOK"."RATING" ORDER BY 2 DESC, 1 DESC;
SELECT "AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" AS "AUTHOR" FROM "AGGREGATION_BOOK_AUTHORS" WHERE ("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" IN (%s) AND "AGGREGATION_BOOK_AUTHORS"."BOOK_ID" = %s);
SELECT "AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" AS "AUTHOR" FROM "AGGREGATION_BOOK_AUTHORS" WHERE ("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" IN (%s) AND "AGGREGATION_BOOK_AUTHORS"."BOOK_ID" = %s);
SELECT "AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" AS "AUTHOR" FROM "AGGREGATION_BOOK_AUTHORS" WHERE ("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" IN (%s) AND "AGGREGATION_BOOK_AUTHORS"."BOOK_ID" = %s);
SELECT "AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" AS "AUTHOR" FROM "AGGREGATION_BOOK_AUTHORS" WHERE ("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" IN (%s) AND "AGGREGATION_BOOK_AUTHORS"."BOOK_ID" = %s);
SELECT "AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" AS "AUTHOR" FROM "AGGREGATION_BOOK_AUTHORS" WHERE ("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" IN (%s) AND "AGGREGATION_BOOK_AUTHORS"."BOOK_ID" = %s);
SELECT "AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" AS "AUTHOR" FROM "AGGREGATION_BOOK_AUTHORS" WHERE ("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" IN (%s) AND "AGGREGATION_BOOK_AUTHORS"."BOOK_ID" = %s);
SELECT "AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" AS "AUTHOR" FROM "AGGREGATION_BOOK_AUTHORS" WHERE ("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" IN (%s) AND "AGGREGATION_BOOK_AUTHORS"."BOOK_ID" = %s);
SELECT "AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" AS "AUTHOR" FROM "AGGREGATION_BOOK_AUTHORS" WHERE ("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" IN (%s) AND "AGGREGATION_BOOK_AUTHORS"."BOOK_ID" = %s);
SELECT "AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" AS "AUTHOR" FROM "AGGREGATION_BOOK_AUTHORS" WHERE ("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" IN (%s) AND "AGGREGATION_BOOK_AUTHORS"."BOOK_ID" = %s);
SELECT "AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" AS "AUTHOR" FROM "AGGREGATION_BOOK_AUTHORS" WHERE ("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" IN (%s, %s) AND "AGGREGATION_BOOK_AUTHORS"."BOOK_ID" = %s);
SELECT "AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" AS "AUTHOR" FROM "AGGREGATION_BOOK_AUTHORS" WHERE ("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" IN (%s, %s) AND "AGGREGATION_BOOK_AUTHORS"."BOOK_ID" = %s);
SELECT "AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" AS "AUTHOR" FROM "AGGREGATION_BOOK_AUTHORS" WHERE ("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" IN (%s, %s) AND "AGGREGATION_BOOK_AUTHORS"."BOOK_ID" = %s);
SELECT "AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" AS "AUTHOR" FROM "AGGREGATION_BOOK_AUTHORS" WHERE ("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" IN (%s, %s, %s) AND "AGGREGATION_BOOK_AUTHORS"."BOOK_ID" = %s);
SELECT "AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" AS "AUTHOR" FROM "AGGREGATION_BOOK_AUTHORS" WHERE ("AGGREGATION_BOOK_AUTHORS"."AUTHOR_ID" IN (%s, %s, %s) AND "AGGREGATION_BOOK_AUTHORS"."BOOK_ID" = %s);
SELECT "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION" FROM "AGGREGATION_PUBLISHER" INNER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_PUBLISHER"."ID" = "AGGREGATION_BOOK"."PUBLISHER_ID") WHERE "AGGREGATION_BOOK"."PRICE" < %s ORDER BY "AGGREGATION_PUBLISHER"."ID" ASC;
SELECT "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION" FROM "AGGREGATION_PUBLISHER" ORDER BY "AGGREGATION_PUBLISHER"."ID" ASC FETCH FIRST 1 ROWS ONLY;
SELECT "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION" FROM "AGGREGATION_PUBLISHER" WHERE "AGGREGATION_PUBLISHER"."ID" IN (SELECT U2."PUBLISHER_ID" AS "PUBLISHER_ID" FROM "AGGREGATION_AUTHOR" U0 LEFT OUTER JOIN "AGGREGATION_BOOK_AUTHORS" U1 ON (U0."ID" = U1."AUTHOR_ID") LEFT OUTER JOIN "AGGREGATION_BOOK" U2 ON (U1."BOOK_ID" = U2."ID") GROUP BY U2."PUBLISHER_ID");
SELECT "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION" FROM "AGGREGATION_PUBLISHER";
SELECT "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION", ((SELECT (1) AS "A" FROM "AGGREGATION_BOOK" U0 WHERE U0."PUBLISHER_ID" = ("AGGREGATION_BOOK"."PUBLISHER_ID") FETCH FIRST 1 ROWS ONLY) IS NOT NULL) AS "BOOKS_EXISTS", COUNT("AGGREGATION_BOOK"."ID") AS "BOOKS_COUNT" FROM "AGGREGATION_PUBLISHER" LEFT OUTER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_PUBLISHER"."ID" = "AGGREGATION_BOOK"."PUBLISHER_ID") GROUP BY "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION", ((SELECT (1) AS "A" FROM "AGGREGATION_BOOK" U0 WHERE U0."PUBLISHER_ID" = ("AGGREGATION_BOOK"."PUBLISHER_ID") FETCH FIRST 1 ROWS ONLY) IS NOT NULL);
SELECT "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION", (SELECT U0."PUBDATE" AS "PUBDATE" FROM "AGGREGATION_BOOK" U0 WHERE U0."PUBLISHER_ID" = ("AGGREGATION_PUBLISHER"."ID") ORDER BY 1 DESC FETCH FIRST 1 ROWS ONLY) AS "LATEST_BOOK_PUBDATE", COUNT("AGGREGATION_BOOK"."ID") AS "COUNT" FROM "AGGREGATION_PUBLISHER" LEFT OUTER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_PUBLISHER"."ID" = "AGGREGATION_BOOK"."PUBLISHER_ID") GROUP BY "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION";
SELECT "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION", COUNT("AGGREGATION_BOOK"."ID") AS "NUM_BOOKS" FROM "AGGREGATION_PUBLISHER" INNER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_PUBLISHER"."ID" = "AGGREGATION_BOOK"."PUBLISHER_ID") WHERE "AGGREGATION_BOOK"."PRICE" < %s GROUP BY "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION" HAVING COUNT("AGGREGATION_BOOK"."ID") > %s ORDER BY "AGGREGATION_PUBLISHER"."ID" ASC;
SELECT "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION", COUNT("AGGREGATION_BOOK"."ID") AS "NUM_BOOKS" FROM "AGGREGATION_PUBLISHER" INNER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_PUBLISHER"."ID" = "AGGREGATION_BOOK"."PUBLISHER_ID") WHERE "AGGREGATION_BOOK"."PRICE" < %s GROUP BY "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION" HAVING COUNT("AGGREGATION_BOOK"."ID") > %s;
SELECT "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION", COUNT("AGGREGATION_BOOK"."ID") AS "NUM_BOOKS" FROM "AGGREGATION_PUBLISHER" LEFT OUTER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_PUBLISHER"."ID" = "AGGREGATION_BOOK"."PUBLISHER_ID") GROUP BY "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION" HAVING COUNT("AGGREGATION_BOOK"."ID") > %s ORDER BY "AGGREGATION_PUBLISHER"."ID" ASC;
SELECT "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION", COUNT("AGGREGATION_BOOK"."ID") AS "NUM_BOOKS" FROM "AGGREGATION_PUBLISHER" LEFT OUTER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_PUBLISHER"."ID" = "AGGREGATION_BOOK"."PUBLISHER_ID") GROUP BY "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION" HAVING COUNT("AGGREGATION_BOOK"."ID") BETWEEN %s AND %s ORDER BY "AGGREGATION_PUBLISHER"."ID" ASC;
SELECT "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION", COUNT("AGGREGATION_BOOK"."ID") AS "NUM_BOOKS" FROM "AGGREGATION_PUBLISHER" LEFT OUTER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_PUBLISHER"."ID" = "AGGREGATION_BOOK"."PUBLISHER_ID") GROUP BY "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION" HAVING COUNT("AGGREGATION_BOOK"."ID") BETWEEN %s AND %s ORDER BY "AGGREGATION_PUBLISHER"."ID" ASC;
SELECT "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION", COUNT("AGGREGATION_BOOK"."ID") AS "NUM_BOOKS" FROM "AGGREGATION_PUBLISHER" LEFT OUTER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_PUBLISHER"."ID" = "AGGREGATION_BOOK"."PUBLISHER_ID") GROUP BY "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION" HAVING COUNT("AGGREGATION_BOOK"."ID") IN (%s, %s) ORDER BY "AGGREGATION_PUBLISHER"."ID" ASC;
SELECT "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION", COUNT("AGGREGATION_BOOK"."ID") AS "NUM_BOOKS" FROM "AGGREGATION_PUBLISHER" LEFT OUTER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_PUBLISHER"."ID" = "AGGREGATION_BOOK"."PUBLISHER_ID") GROUP BY "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION" HAVING COUNT("AGGREGATION_BOOK"."ID") IS NULL;
SELECT "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION", COUNT("AGGREGATION_BOOK"."ID") AS "NUM_BOOKS" FROM "AGGREGATION_PUBLISHER" LEFT OUTER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_PUBLISHER"."ID" = "AGGREGATION_BOOK"."PUBLISHER_ID") INNER JOIN "AGGREGATION_BOOK" T3 ON ("AGGREGATION_PUBLISHER"."ID" = T3."PUBLISHER_ID") WHERE T3."PRICE" < %s GROUP BY "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION" HAVING COUNT("AGGREGATION_BOOK"."ID") > %s ORDER BY "AGGREGATION_PUBLISHER"."ID" ASC;
SELECT "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION", GREATEST(AVG("AGGREGATION_BOOK"."RATING"), AVG("AGGREGATION_BOOK"."PRICE")) AS "PRICE_OR_MEDIAN" FROM "AGGREGATION_PUBLISHER" LEFT OUTER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_PUBLISHER"."ID" = "AGGREGATION_BOOK"."PUBLISHER_ID") GROUP BY "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION" HAVING GREATEST(AVG("AGGREGATION_BOOK"."RATING"), AVG("AGGREGATION_BOOK"."PRICE")) >= ("AGGREGATION_PUBLISHER"."NUM_AWARDS") ORDER BY "AGGREGATION_PUBLISHER"."NUM_AWARDS" ASC;
SELECT "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION", GREATEST(AVG("AGGREGATION_BOOK"."RATING"), "AGGREGATION_PUBLISHER"."NUM_AWARDS") AS "RATING_OR_NUM_AWARDS" FROM "AGGREGATION_PUBLISHER" LEFT OUTER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_PUBLISHER"."ID" = "AGGREGATION_BOOK"."PUBLISHER_ID") GROUP BY "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION" HAVING GREATEST(AVG("AGGREGATION_BOOK"."RATING"), "AGGREGATION_PUBLISHER"."NUM_AWARDS") > ("AGGREGATION_PUBLISHER"."NUM_AWARDS") ORDER BY "AGGREGATION_PUBLISHER"."NUM_AWARDS" ASC;
SELECT "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION", SUM("AGGREGATION_BOOK"."PRICE") AS "BOOK__PRICE__SUM" FROM "AGGREGATION_PUBLISHER" LEFT OUTER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_PUBLISHER"."ID" = "AGGREGATION_BOOK"."PUBLISHER_ID") GROUP BY "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION" ORDER BY "AGGREGATION_PUBLISHER"."NAME" ASC;
SELECT "AGGREGATION_PUBLISHER"."NAME" AS "NAME" FROM "AGGREGATION_PUBLISHER" LEFT OUTER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_PUBLISHER"."ID" = "AGGREGATION_BOOK"."PUBLISHER_ID") GROUP BY "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION";
SELECT "AGGREGATION_PUBLISHER"."NAME" AS "NAME", (COALESCE(AVG("AGGREGATION_BOOK"."RATING"), CAST(%s AS DOUBLE)) * CAST(%s AS DOUBLE)) AS "RATING" FROM "AGGREGATION_PUBLISHER" LEFT OUTER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_PUBLISHER"."ID" = "AGGREGATION_BOOK"."PUBLISHER_ID") GROUP BY "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION" ORDER BY 1 ASC;
SELECT "AGGREGATION_PUBLISHER"."NAME" AS "NAME", COALESCE(MIN("AGGREGATION_BOOK"."PUBDATE"), CAST(%s AS DATE)) AS "EARLIEST_PUBDATE" FROM "AGGREGATION_PUBLISHER" LEFT OUTER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_PUBLISHER"."ID" = "AGGREGATION_BOOK"."PUBLISHER_ID") GROUP BY "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION" ORDER BY 1 ASC;
SELECT "AGGREGATION_PUBLISHER"."NAME" AS "NAME", COALESCE(MIN("AGGREGATION_BOOK"."PUBDATE"), "DJDB2I_GROUPING"."G1") AS "EARLIEST_PUBDATE" FROM "AGGREGATION_PUBLISHER" LEFT OUTER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_PUBLISHER"."ID" = "AGGREGATION_BOOK"."PUBLISHER_ID") CROSS JOIN LATERAL (SELECT DATE(CURRENT_TIMESTAMP) AS "G1" FROM SYSIBM.SYSDUMMY1) AS "DJDB2I_GROUPING" GROUP BY "AGGREGATION_PUBLISHER"."ID", "AGGREGATION_PUBLISHER"."NAME", "AGGREGATION_PUBLISHER"."NUM_AWARDS", "AGGREGATION_PUBLISHER"."DURATION", "DJDB2I_GROUPING"."G1" ORDER BY 1 ASC;
SELECT "AGGREGATION_PUBLISHER"."NAME" AS "NAME", COUNT("AGGREGATION_BOOK"."ID") AS "BOOKS", COALESCE(SUM("AGGREGATION_BOOK"."PAGES"), CAST(%s AS INTEGER)) AS "PAGES" FROM "AGGREGATION_PUBLISHER" LEFT OUTER JOIN "AGGREGATION_BOOK" ON ("AGGREGATION_PUBLISHER"."ID" = "AGGREGATION_BOOK"."PUBLISHER_ID") GROUP BY "AGGREGATION_PUBLISHER"."NAME" HAVING COUNT("AGGREGATION_BOOK"."ID") = %s;
SELECT "AGGREGATION_STORE_BOOKS"."BOOK_ID" AS "BOOK" FROM "AGGREGATION_STORE_BOOKS" WHERE ("AGGREGATION_STORE_BOOKS"."BOOK_ID" IN (%s, %s, %s) AND "AGGREGATION_STORE_BOOKS"."STORE_ID" = %s);
SELECT "AGGREGATION_STORE_BOOKS"."BOOK_ID" AS "BOOK" FROM "AGGREGATION_STORE_BOOKS" WHERE ("AGGREGATION_STORE_BOOKS"."BOOK_ID" IN (%s, %s, %s, %s) AND "AGGREGATION_STORE_BOOKS"."STORE_ID" = %s);
