SELECT "DJDB2I_GROUPING"."G1" AS "EXISTS1", COUNT(*) AS "TOTAL" FROM "AGGREGATION_PUBLISHER" CROSS JOIN LATERAL (SELECT ((SELECT (1) AS "A" FROM "AGGREGATION_BOOK" U0 WHERE (U0."PAGES" > %s AND U0."PUBLISHER_ID" = ("AGGREGATION_PUBLISHER"."ID")) FETCH FIRST 1 ROWS ONLY) IS NOT NULL) AS "G1" FROM SYSIBM.SYSDUMMY1) AS "DJDB2I_GROUPING" GROUP BY "DJDB2I_GROUPING"."G1";
SELECT "DJDB2I_GROUPING"."G1" AS "QUERY1", COUNT(*) AS "TOTAL" FROM "AGGREGATION_PUBLISHER" CROSS JOIN LATERAL (SELECT (SELECT COUNT(U0."ID") AS "COUNT" FROM "AGGREGATION_BOOK" U0 WHERE (U0."PAGES" > %s AND U0."PUBLISHER_ID" = ("AGGREGATION_PUBLISHER"."ID")) GROUP BY U0."PUBLISHER_ID") AS "G1" FROM SYSIBM.SYSDUMMY1) AS "DJDB2I_GROUPING" GROUP BY "DJDB2I_GROUPING"."G1";
SELECT "DJDB2I_GROUPING"."G1" AS "QUERYSET1", COUNT(*) AS "TOTAL" FROM "AGGREGATION_PUBLISHER" CROSS JOIN LATERAL (SELECT (SELECT COUNT(U0."ID") AS "COUNT" FROM "AGGREGATION_BOOK" U0 WHERE (U0."PAGES" > %s AND U0."PUBLISHER_ID" = ("AGGREGATION_PUBLISHER"."ID")) GROUP BY U0."PUBLISHER_ID") AS "G1" FROM SYSIBM.SYSDUMMY1) AS "DJDB2I_GROUPING" GROUP BY "DJDB2I_GROUPING"."G1";
SELECT "DJDB2I_GROUPING"."G1" AS "SUBQUERY1", COUNT(*) AS "TOTAL" FROM "AGGREGATION_PUBLISHER" CROSS JOIN LATERAL (SELECT (SELECT COUNT(U0."ID") AS "COUNT" FROM "AGGREGATION_BOOK" U0 WHERE (U0."PAGES" > %s AND U0."PUBLISHER_ID" = ("AGGREGATION_PUBLISHER"."ID")) GROUP BY U0."PUBLISHER_ID") AS "G1" FROM SYSIBM.SYSDUMMY1) AS "DJDB2I_GROUPING" GROUP BY "DJDB2I_GROUPING"."G1";
